window.Incorporacoes=(()=>{
 let generation=0;
 const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const price=v=>v.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
 async function render(){const main=document.querySelector('#main'),run=++generation;main.innerHTML='<h1>Vanguarda Incorporações</h1><p role="status">Carregando vitrine…</p>';try{
 await sessionReady;const response=await fetch('/api/incorporacoes',{cache:'no-store'});if(!response.ok)throw Error(response.status===401?'Sem sessão ou permissão comercial.':'Não foi possível carregar a vitrine.');const items=await response.json();if(run!==generation||!location.hash.startsWith('#incorporacoes'))return;
 const id=location.hash.split('/')[1];if(id){const p=items.find(p=>p.id===id);if(!p){main.innerHTML='<h1>Imóvel não encontrado</h1><a href="#incorporacoes">Voltar à vitrine</a>';return;}
 main.innerHTML=`<a href="#incorporacoes">← Voltar à vitrine</a><h1>${esc(p.name)}</h1><p>Exemplo fictício · sem oferta comercial</p><div class="property-gallery"><img src="/property.svg" alt="Ilustração fictícia de fachada"><img src="/property.svg" alt="Estudo ilustrativo do empreendimento" style="filter:hue-rotate(35deg)"></div><section class="card"><h2>${esc(p.location)}</h2><p>${esc(p.type)} · ${p.area} m² · ${p.bedrooms} dormitórios</p><p>${price(p.price)} — preço fictício · ${esc(p.status)}</p><p>${esc(p.description)}</p><ul>${p.features.map(f=>`<li>${esc(f)}</li>`).join('')}</ul><p>Entrega: ${esc(p.delivery)}</p><button id="interest" class="button primary">Registrar interesse</button><p id="interest-status" role="status" aria-live="polite"></p></section>`;
 document.querySelector('#interest').onclick=async e=>{e.target.disabled=true;const status=document.querySelector('#interest-status');status.textContent='Salvando interesse…';try{const r=await fetch('/api/interests',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':VanguardaSession.csrf},body:JSON.stringify({propertyId:p.id})});if(!r.ok)throw Error();status.textContent='Interesse registrado no servidor. Este imóvel é fictício.';}catch{status.textContent='Não foi possível salvar o interesse. Tente novamente.';e.target.disabled=false;}};return;}
 main.innerHTML='<div class="eyebrow">Vitrine interna</div><h1>Vanguarda Incorporações</h1><p>Exemplos fictícios. Preços, áreas, imagens e situações ilustrativos, sem oferta comercial. Dados separados dos indicadores de risco PMO.</p><div class="filters filter-bar"><label>Busca<input id="property-search" type="search" placeholder="Nome do empreendimento"></label><label>Localização<select id="property-location"><option value="">Todas</option>'+[...new Set(items.map(p=>p.location))].map(v=>`<option>${esc(v)}</option>`).join('')+'</select></label><label>Preço fictício<select id="property-price"><option value="">Todos</option><option value="500000">Até R$ 500 mil</option><option value="higher">Acima de R$ 500 mil</option></select></label><label>Tipo<select id="property-type"><option value="">Todos</option><option>Apartamento</option><option>Casa</option></select></label><label>Situação<select id="property-status"><option value="">Todas</option>'+[...new Set(items.map(p=>p.status))].map(v=>`<option>${esc(v)}</option>`).join('')+'</select></label></div><p id="property-count" role="status"></p><div class="project-grid" id="property-grid"></div>';
 const update=()=>{const value=id=>document.querySelector('#property-'+id).value;const selected=items.filter(p=>p.name.toLowerCase().includes(value('search').toLowerCase())&&(!value('location')||p.location===value('location'))&&(!value('type')||p.type===value('type'))&&(!value('status')||p.status===value('status'))&&(!value('price')||(value('price')==='higher'?p.price>500000:p.price<=500000)));document.querySelector('#property-count').textContent=selected.length+' empreendimentos fictícios';document.querySelector('#property-grid').innerHTML=selected.map(p=>`<article class="card property-card"><img src="/property.svg" alt="Fachada ilustrativa fictícia"><span class="tag">Exemplo fictício</span><h2>${esc(p.name)}</h2><p>${esc(p.location)}</p><p>${esc(p.type)} · ${p.area} m² · ${p.bedrooms} dormitórios</p><p class="property-price">${price(p.price)} <span>(fictício)</span></p><p>${esc(p.status)}</p><a class="button" href="#incorporacoes/${p.id}">Ver detalhes</a></article>`).join('')||'<p>Nenhum empreendimento encontrado. Ajuste os filtros.</p>';};main.querySelectorAll('input,select').forEach(el=>el.addEventListener('input',update));update();
 }catch(e){if(run===generation)main.innerHTML=`<h1>Vanguarda Incorporações</h1><p role="alert">${esc(e.message)}</p><button class="button" id="retry-property">Tentar novamente</button>`;document.querySelector('#retry-property')?.addEventListener('click',render);}}
 return {render};
})();
